import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0013: 为什么未知执行结果不能直接重试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0013-why-unknown-outcomes-are-never-blindly-retried.md","filePath":"zh/adr/ADR-0013-why-unknown-outcomes-are-never-blindly-retried.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0013-why-unknown-outcomes-are-never-blindly-retried.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0013-为什么未知执行结果不能直接重试" tabindex="-1">ADR-0013: 为什么未知执行结果不能直接重试 <a class="header-anchor" href="#adr-0013-为什么未知执行结果不能直接重试" aria-label="Permalink to “ADR-0013: 为什么未知执行结果不能直接重试”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：recovery-engine.md §6.6，ADR-0008</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>恢复动作执行到一半进程崩溃（或超时被杀），attempt 的 outcome 停在 NULL。 此时动作<strong>可能已生效</strong>（服务已重启）、可能没生效、也可能生效了一半。 直接重试的后果：双执行副作用——服务被重启两次、网络变更下发两次、 幂等声明错误时状态被破坏。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p><code>OutcomeUnknown</code> 是一等状态：崩溃恢复把未终态运行标记为 outcome-unknown， <strong>停止自动处理</strong>，以资源现状为唯一事实重新走&quot;探测 → 诊断&quot;路径； 未知结果的运行绝不沿用旧诊断直接重执行（P0 验收：未知结果的运行不得盲目重试）。 只有新诊断再次给出故障 + 新计划时才可能有新动作。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>直接重试一次</strong>：副作用翻倍（见背景）；且掩盖了&quot;上一轮到底发生了什么&quot;。</li><li><strong>标记失败并放弃</strong>：把可自愈的故障推给人，违背自愈目标。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：副作用有界；事实链（执行了什么、结果未知、新诊断是什么）完整可审计。 缺点：恢复路径多一次诊断周期；对探针质量依赖更高（诊断必须基于当前健康）。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li><code>resume_unfinished</code> + <code>RecoveryRunStatus::OutcomeUnknown</code> + 引擎事件 <code>recovery.outcome_unknown</code>（通知事件同名）共同实现。</li><li>幂等声明（<code>idempotent = true</code>）是优化不是豁免：未知结果一律重诊断。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};